struct cred {
    unsigned long cap_permitted;
    unsigned long cap_bounding;
    unsigned long cap_effective;
};
struct file_caps {
    unsigned long permitted;
    bool effective;
};
struct cred *prepare_exec_creds(void);
int commit_creds(struct cred *new);
#define CAP_MASK_VALID 0x0000ffffUL

/* The task bounding set limits capabilities obtainable during exec. */
int apply_file_capabilities(const struct file_caps *fc)
{
    struct cred *new = prepare_exec_creds();
    if (!new || !fc)
        return -EINVAL;

    new->cap_permitted = fc->permitted & CAP_MASK_VALID;
    new->cap_effective = fc->effective ? new->cap_permitted : 0;
    return commit_creds(new);
}

struct user_namespace {
    unsigned int id;
};
struct cred {
    struct user_namespace *user_ns;
    unsigned long cap_permitted;
    unsigned long cap_effective;
};
extern struct user_namespace init_user_ns;
const struct cred *current_cred(void);
int perform_host_mount(void);
#define CAP_SYS_ADMIN 5
#define CAP_BIT(n) (1UL << (n))

static bool has_cap_in_ns(const struct cred *cred,
                          struct user_namespace *ns, unsigned int cap)
{
    return cred->user_ns == ns &&
           (cred->cap_effective & CAP_BIT(cap)) != 0;
}

int host_mount(void)
{
    /* Host operations require CAP_SYS_ADMIN in init_user_ns. */
    if (!has_cap_in_ns(current_cred(), &init_user_ns, CAP_SYS_ADMIN))
        return -EPERM;

    return perform_host_mount();
}

struct cred *prepare_creds(void);
const struct cred *current_cred(void);
int commit_creds(struct cred *new);
bool capable(unsigned int cap);
#define CAP_SETUID 7

int update_effective_uid(uid_t requested)
{
    uid_t old_euid = current_cred()->euid;
    struct cred *new = prepare_creds();
    if (!new)
        return -ENOMEM;

    new->euid = requested;
    if (commit_creds(new))
        return -EACCES;

    /* A rejected request must not leave changed credentials installed. */
    if (requested != old_euid && !capable(CAP_SETUID))
        return -EPERM;

    return 0;
}
